if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$active=(int)($_POST['active']??0);if($id!==(int)current_user()['id']){$st=$pdo->prepare("UPDATE users SET is_active=? WHERE id=? AND role='customer'");$st->execute([$active,$id]);flash('Customer account updated.');}else flash('You cannot deactivate your own account here.','error');redirect('/lakshmi-electricals/admin/users.php');}
$users=$pdo->query("SELECT id,name,email,phone,is_active,created_at FROM users WHERE role='customer' ORDER BY created_at DESC")->fetchAll();$pageTitle='Manage customers';require __DIR__.'/../includes/header.php';?>
<div class="admin-layout"><aside class="admin-sidebar"><span class="eyebrow">MANAGEMENT</span><h2>Admin panel</h2><a href="/lakshmi-electricals/admin/dashboard.php">Dashboard</a><a href="/lakshmi-electricals/admin/categories.php">Categories</a><a href="/lakshmi-electricals/admin/products.php">Products</a><a href="/lakshmi-electricals/admin/orders.php">Order requests</a><a class="active" href="/lakshmi-electricals/admin/users.php">Customers</a></aside><section class="admin-content"><div class="section-heading"><div><span class="eyebrow">ACCOUNTS</span><h1>Customer accounts</h1></div></div><div class="panel"><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Joined</th><th>Status / action</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?= e($u['name']) ?></td><td><?= e($u['email']) ?></td><td><?= e($u['phone']) ?></td><td><?= e(date('d M Y',strtotime($u['created_at']))) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><input type="hidden" name="active" value="<?= $u['is_active']?0:1 ?>"><span class="status"><?= $u['is_active']?'Active':'Inactive' ?></span><button class="btn btn-outline small-btn"><?= $u['is_active']?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div></section></div>
